// --- API-013: Zerar Turma ---
export const ZerarTurmaRespostaSchema = z.object({
  sucesso: z.literal(true),
  novaRodada: z.number().int().positive(),
  etapaLiberada: z.literal(1)
});

// --- Schema de Saída da IA no Preparo (API-018) ---
export const NoticiaGeradaSchema = z.object({
  id: z.string().max(30),
  suporte: SuporteEnum,
  manchete: z.string().max(40),
  legenda: z.string().max(120),
  localEvento: LocalLugarEnum,
  onde: LocalLugarEnum.nullable(),
  campoOndePreenchido: z.boolean(),
  imagemUrl: z.string().url()
});

export const CasoNovoGeradoSchema = z.object({
  tema: z.string().max(60),
  materiaA: z.object({
    titulo: z.string().max(40),
    dia: z.string().max(20),
    imagemUrl: z.string().url()
  }),
  materiaB: z.object({
    titulo: z.string().max(40),
    dia: z.string().max(20),
    imagemUrl: z.string().url()
  }),
  quandoFicha: z.string().nullable()
});

export const PacoteNoticiasGeradoSchema = z.object({
  disciplina: z.string().max(40),
  tema: z.string().max(60),
  assuntos: z.string().max(100),
  localEvento: LocalLugarEnum,
  materias: z.array(NoticiaGeradaSchema).length(3),
  casoNovo: CasoNovoGeradoSchema
});
export type PacoteNoticiasGerado = z.infer<typeof PacoteNoticiasGeradoSchema>;
